const today = new Date().toLocaleDateString('ko-KR', { timeZone:'Asia/Seoul' });
const SEARX = 'http://127.0.0.1:8888/search';
const queries = ['과기정통부 AI 인공지능 공모 접수중','중소벤처기업부 AI 지원사업 공고 모집','산업통상자원부 인공지능 공모 신청','NIPA 정보통신산업진흥원 AI 공모 접수','IRIS 범부처 인공지능 R&D 공모','AI 인공지능 정부 지원사업 공모 신청기간'];
const seen = new Set(); const results = [];
for(const q of queries){ try{ const r = await this.helpers.httpRequest({ method:'GET', url:SEARX, qs:{ q, format:'json', language:'ko-KR', safesearch:0 }, headers:{'User-Agent':'Mozilla/5.0'}, json:true, timeout:15000 }); for(const it of ((r&&r.results)||[]).slice(0,8)){ if(!it.url||seen.has(it.url)) continue; seen.add(it.url); results.push({ url:it.url, title:it.title||'', snippet:it.content||'' }); } }catch(e){} }
const top = results.slice(0,12); const docs=[];
for(const d of top){ let body=d.snippet||''; try{ const html = await this.helpers.httpRequest({ method:'GET', url:d.url, headers:{'User-Agent':'Mozilla/5.0'}, timeout:12000 }); const text = String(html).replace(/<[^>]+>/g,' ').replace(/&[a-z]+;/gi,' ').replace(/\s+/g,' ').trim(); if(text.length>200) body=text.slice(0,4000); }catch(e){} for(let i=0;i<body.length && i<2400;i+=800){ docs.push({ url:d.url, title:d.title, text:body.slice(i,i+800) }); } }
return [{ json:{ today, docs, found: results.length } }];

const inp = $input.first().json; const today=inp.today; const docs=inp.docs||[];
const EMB='http://127.0.0.1:11434/api/embeddings'; const self=this;
async function embed(t){ const r=await self.helpers.httpRequest({ method:'POST', url:EMB, body:{ model:'nomic-embed-text', prompt:t }, json:true, timeout:20000 }); return (r&&r.embedding)||[]; }
function cos(a,b){ let d=0,na=0,nb=0; const n=Math.min(a.length,b.length); for(let i=0;i<n;i++){ d+=a[i]*b[i]; na+=a[i]*a[i]; nb+=b[i]*b[i]; } return d/(Math.sqrt(na)*Math.sqrt(nb)+1e-9); }
const query='오늘 '+today+' 기준 마감 전 접수중인 AI 인공지능 정부 공모사업 신청기간 주관기관 지원대상';
let qv=[]; try{ qv=await embed(query); }catch(e){}
const scored=[];
for(const doc of docs){ try{ const v=await embed(doc.text); scored.push(Object.assign({}, doc, { score: qv.length? cos(qv,v):0 })); }catch(e){ scored.push(Object.assign({}, doc, { score:0 })); } }
scored.sort((a,b)=>b.score-a.score);
const topK=scored.slice(0,8);
const ctx=topK.map((d,i)=>'['+(i+1)+'] 출처:'+d.url+' | 제목:'+d.title+'\n'+d.text).join('\n\n');
const sources=topK.map((d,i)=>({ n:i+1, url:d.url, title:d.title }));
const sys='너는 정부지원사업 분석가다. 주어진 검색 컨텍스트에 실제로 있는 사실만 사용하고 없는 내용은 절대 지어내지 않는다. 한국어로만 답한다.';
const user='오늘은 '+today+'. 아래 검색 컨텍스트에서 마감 전(현재 접수중인) AI 인공지능 정부 공모사업만 골라 HTML table로 정리하라. 칼럼 순서: 사업명 | 주관기관 | 신청기간 | 지원대상 | 출처. 신청기간이나 지원대상이 컨텍스트에 없으면 정보없음 으로 표기. 출처 칼럼에는 대괄호 번호 형식으로 컨텍스트 번호를 적어라. 접수중 AI 공모를 찾지 못하면 <p>오늘 기준 확인된 접수중 AI 공모가 없습니다.</p> 만 출력. 설명·인사 없이 표 또는 그 문구만.\n\n[검색 컨텍스트]\n'+ctx;
const llmBody={ model:'qwen2.5:3b', messages:[{role:'system',content:sys},{role:'user',content:user}], temperature:0.2, stream:false };
return [{ json:{ today, llm_body: JSON.stringify(llmBody), sources, found: inp.found } }];

const r=$input.first().json||{};
let content=(r.choices&&r.choices[0]&&r.choices[0].message&&r.choices[0].message.content)||'';
content=content.replace(/^```(?:html)?\s*/i,'').replace(/```\s*$/,'').trim();
let today='', sources=[]; try{ const m=$('임베딩RAG').first().json; today=m.today; sources=m.sources||[]; }catch(e){}
let srcHtml='';
if(sources.length){ srcHtml='<h3>출처</h3><ol>'+sources.map(s=>'<li>['+s.n+'] <a href="'+s.url+'">'+(s.title||s.url)+'</a></li>').join('')+'</ol>'; }
const html=['<!DOCTYPE html>','<html lang="ko"><head><meta charset="UTF-8"><title>AI 정부공모 브리핑(로컬)</title>','<style>','body{font-family:"Pretendard","맑은 고딕",sans-serif;max-width:860px;margin:24px auto;padding:0 18px;color:#1f2a44;line-height:1.6}','h1{border-bottom:3px solid #16a34a;padding-bottom:8px;color:#15803d}','h3{margin-top:24px;color:#34507e}','table{border-collapse:collapse;width:100%;margin:14px 0;font-size:.93rem}','th,td{border:1px solid #dde3ee;padding:8px 10px;text-align:left;vertical-align:top}','th{background:#f0fdf4;color:#15803d}','a{color:#2e6fae}','ol li{margin:3px 0;word-break:break-all;font-size:.85rem}','.meta{background:#f5f7fb;border:1px solid #dde3ee;border-radius:10px;padding:10px 14px;margin:12px 0;color:#475569;font-size:.9rem}','.footer{margin-top:30px;padding-top:14px;border-top:1px solid #dde3ee;color:#6b7793;font-size:.84rem}','</style></head><body>','<h1>🔎 오늘의 AI 정부공모 브리핑 (로컬·무료)</h1>','<div class="meta">기준일: '+today+' · 검색: SearXNG · 임베딩: nomic-embed-text · 요약: qwen2.5:3b (모두 로컬·무료)</div>',content,srcHtml,'<div class="footer">🤖 로컬 RAG 자동 생성 · 매일 08:30 · 공식 공고를 반드시 재확인하세요</div>','</body></html>'].join('\n');
return [{ json:{ html, today } }];
